import {AnchoredOverlay, Text, Token} from '@primer/react'
import styles from './AllOrgsTokenComponent.module.css'
import {RoleAvatarSpread} from './RoleAvatarSpread'
import {OrgAccessTargetType, type OrgAccess} from '../types/role-assignments'
import {AlertFillIcon} from '@primer/octicons-react'
import {useRef, useState} from 'react'
import {testIdProps} from '@github-ui/test-id-props'

interface AllOrgsTokenComponentProps {
  orgAccess: OrgAccess
  roleName: string
  allOrganizationAvatarURLs: string[]
}

export function AllOrgsTokenComponent({orgAccess, roleName, allOrganizationAvatarURLs}: AllOrgsTokenComponentProps) {
  const [isOpen, setOpen] = useState(false)
  const buttonRef = useRef<HTMLButtonElement>(null)

  return (
    <>
      {orgAccess.target === OrgAccessTargetType.AllOrgs && (
        <Token
          leadingVisual={() => <RoleAvatarSpread avatarURLs={allOrganizationAvatarURLs} />}
          text="all organizations"
          className={styles.sourceToken}
          {...testIdProps('all-orgs-token')}
        />
      )}
      {orgAccess.target === OrgAccessTargetType.SomeOrgs && (
        <>
          <span>
            <Token
              as="button"
              ref={buttonRef}
              onClick={() => setOpen(!isOpen)}
              leadingVisual={() => <RoleAvatarSpread avatarURLs={allOrganizationAvatarURLs} />}
              text={`${orgAccess.selected_count} / ${orgAccess.total_count} organizations`}
              className={styles.sourceToken}
              {...testIdProps('some-orgs-token')}
            />
            <AlertFillIcon size={12} className="fgColor-danger ml-1" {...testIdProps('some-orgs-alert-icon')} />
          </span>
          <AnchoredOverlay
            open={isOpen}
            onOpen={() => {
              setOpen(true)
            }}
            onClose={() => {
              setOpen(false)
            }}
            renderAnchor={null}
            anchorRef={buttonRef}
            overlayProps={{
              role: 'dialog',
              'aria-label': 'Organization limit overlay',
              ...testIdProps('some-orgs-overlay'),
            }}
            width="medium"
            side="outside-bottom"
          >
            <div className="tmp-p-3 gap-1">
              <Text as="div" weight="semibold" size="small">
                Role assigned to {orgAccess.selected_count} / {orgAccess.total_count} organizations
              </Text>
              <Text as="div" size="small" className="fgColor-muted">
                Your enterprise has exceeded the organization assignment limit of {orgAccess.limit} for enterprise
                teams. As a result, the remaining {(orgAccess.total_count ?? 0) - (orgAccess.selected_count ?? 0)}{' '}
                organizations were not assigned the {roleName} role.
              </Text>
            </div>
          </AnchoredOverlay>
        </>
      )}
    </>
  )
}
